+#!/usr/bin/env -S node --no-warnings
+import DOMPurifyFactory from "dompurify";
+import hljs from "highlight.js";
+import { JSDOM } from "jsdom";
+import { Marked } from "marked";
+
+const escapeHtml = (s) =>
+  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
+
+const marked = new Marked({ gfm: true, breaks: true });
+
+marked.use({
+  renderer: {
+    code({ text, lang }) {
+      const language = String(lang || "").trim().split(/\s+/)[0];
+      if (language === "mermaid") {
+        return `<div class="mermaid-block"><pre class="mermaid">${escapeHtml(text)}</pre></div>`;
+      }
+      let body;
+      let cls = "";
+      if (language && hljs.getLanguage(language)) {
+        body = hljs.highlight(text, { language, ignoreIllegals: true }).value;
+        cls = ` class="hljs language-${escapeHtml(language)}"`;
+      } else {
+        try {
+          body = hljs.highlightAuto(text).value;
+        } catch {
+          body = escapeHtml(text);
+        }
+      }
+      return `<div class="codeblock"><button type="button" class="copy">Copy</button><pre><code${cls}>${body}</code></pre></div>`;
+    },
+  },
+});
+
+let purifier = null;
+function getPurifier() {
+  if (!purifier) {
+    const { window } = new JSDOM("");
+    purifier = DOMPurifyFactory(window);
+  }
+  return purifier;
+}
+
+// Strict profile: DOMPurify drops javascript: and data: URLs, <script>, event handlers, <style>.
+const MD_PURIFY = {
+  FORBID_TAGS: ["style", "form", "iframe", "object", "embed"],
+  ADD_ATTR: ["checked", "disabled"],
+};
+
+// Mermaid SVG output keeps inline styles and SVG-only tags.
+const SVG_PURIFY = {
+  USE_PROFILES: { svg: true, svgFilters: true, html: true },
+  ADD_TAGS: ["foreignObject"],
+  HTML_INTEGRATION_POINTS: { foreignobject: true },
+  FORBID_TAGS: ["script", "style"],
+  FORBID_ATTR: ["onerror", "onload"],
+};
+
+export function renderMarkdown(src = "") {
+  const raw = marked.parse(String(src ?? ""));
+  return getPurifier().sanitize(raw, MD_PURIFY);
+}
+
+export function sanitizeSvg(svg = "") {
+  return getPurifier().sanitize(String(svg ?? ""), SVG_PURIFY);
+}
