@@ -0,0 +1,73 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+import { renderMarkdown, sanitizeSvg } from "../src/markdown.mjs";
+
+test("GFM markdown renders headings, tables, task lists, autolinks", () => {
+  const html = renderMarkdown("# Title\n\n| a | b |\n| - | - |\n| 1 | 2 |\n\n- [x] done\n\nwww.example.com");
+  assert.match(html, /<h1>Title<\/h1>/);
+  assert.match(html, /<table>/);
+  assert.match(html, /<td>1<\/td>/);
+  assert.match(html, /type="checkbox"/);
+  assert.match(html, /<a href="http:\/\/www\.example\.com">/);
+});
+
+test("fenced code blocks are highlighted and get a copy button", () => {
+  const html = renderMarkdown("```js\nconst a = 1 < 2;\n```");
+  assert.match(html, /<button type="button" class="copy">Copy<\/button>/);
+  assert.match(html, /class="hljs language-js"/);
+  assert.match(html, /<span class="hljs-keyword">const<\/span>/);
+  assert.match(html, /&lt; <span class="hljs-number">2<\/span>/);
+  assert.doesNotMatch(html, /<script/i);
+});
+
+test("unlabelled code blocks still render escaped and copyable", () => {
+  const html = renderMarkdown("```\n<b>&\n```");
+  assert.match(html, /class="copy"/);
+  assert.match(html, /&lt;/);
+  assert.match(html, /&amp;/);
+});
+
+test("mermaid fences become escaped mermaid containers", () => {
+  const html = renderMarkdown("```mermaid\ngraph TD; A[<b>x</b>] --> B\n```");
+  assert.match(html, /<pre class="mermaid">graph TD; A\[&lt;b&gt;x&lt;\/b&gt;\] --&gt; B<\/pre>/);
+  assert.match(html, /class="mermaid-block"/);
+});
+
+test("XSS: script tags, event handlers, javascript: and data:text/html URLs", () => {
+  const html = renderMarkdown(
+    [
+      "<script>alert(1)</script>",
+      "<img src=x onerror=alert(1)>",
+      "[js](javascript:alert(1))",
+      "[data](data:text/html,<script>alert(1)</script>)",
+      '<a href="javascript:alert(2)">raw</a>',
+      '<a href="https://ok.test/">safe</a>',
+    ].join("\n\n"),
+  );
+  assert.doesNotMatch(html, /<script/i);
+  assert.doesNotMatch(html, /onerror/i);
+  assert.match(html, /<img src="x">/);
+  assert.doesNotMatch(html, /href="javascript:/i);
+  assert.doesNotMatch(html, /href="data:text\/html/i);
+  assert.match(html, /<a href="https:\/\/ok\.test\/">safe<\/a>/);
+  // every href that survived must be http(s)
+  for (const [, href] of html.matchAll(/href="([^"]*)"/g)) assert.match(href, /^https?:\/\//);
+});
+
+test("XSS: attribute breakout inside copy-button markup and inline style tags", () => {
+  const html = renderMarkdown('```js" onmouseover="alert(1)\nx\n```\n\n<style>body{display:none}</style>');
+  assert.match(html, /class="copy"/);
+  assert.match(html, /class="mermaid-block"|<div class="codeblock">/);
+  assert.doesNotMatch(html, /<style>/);
+});
+
+test("sanitizeSvg keeps diagram markup but strips scripts and handlers", () => {
