@@ -0,0 +1,61 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+import DOMPurifyFactory from "dompurify";
+import { JSDOM } from "jsdom";
+import { renderMarkdown, sanitizeSvg } from "../src/markdown.mjs";
+
+// jsdom has no SVG layout engine; mermaid only needs these measurements.
+function setupDom() {
+  const dom = new JSDOM('<div id="root"></div>', { pretendToBeVisual: true });
+  const w = dom.window;
+  for (const key of [
+    "window", "document", "navigator", "Element", "HTMLElement", "SVGElement", "SVGSVGElement",
+    "Node", "DOMParser", "XMLSerializer", "MutationObserver", "getComputedStyle",
+  ]) {
+    if (w[key] !== undefined) Object.defineProperty(globalThis, key, { value: w[key], configurable: true, writable: true });
+  }
+  w.SVGElement.prototype.getBBox = () => ({ x: 0, y: 0, width: 100, height: 20 });
+  w.SVGElement.prototype.getComputedTextLength = () => 50;
+  // mermaid calls DOMPurify.<fn> on the imported module; delegate to this window instance
+  const pur = DOMPurifyFactory(w);
+  for (const k of Object.keys(pur)) {
+    if (typeof pur[k] === "function") DOMPurifyFactory[k] = (...args) => pur[k](...args);
+  }
+  Object.defineProperty(globalThis, "DOMPurify", { value: pur, configurable: true, writable: true });
+  return w;
+}
+
+test("mermaid fences render to real sanitized SVG diagrams", async () => {
+  setupDom();
+  const { default: mermaid } = await import("mermaid");
+  mermaid.initialize({ startOnLoad: false, securityLevel: "strict", theme: "neutral" });
+
+  // HTML-ish label must stay inert after sanitization
+  const hostX = document.createElement("div");
+  document.body.appendChild(hostX);
+  const xss = await mermaid.render("t2", 'graph LR; A --> B["<b onclick=alert(1)>Bold</b>"]');
+  const clean = sanitizeSvg(xss.svg);
+  assert.match(clean, /<svg/);
+  assert.match(clean, /Bold/);
+  assert.doesNotMatch(clean, /<script/i);
+  assert.doesNotMatch(clean, /onclick/i);
+
+  const html = renderMarkdown("```mermaid\ngraph TD; A[Start] --> B[End]\n```");
+  const root = document.getElementById("root");
+  root.innerHTML = html;
+
+  const block = root.querySelector("pre.mermaid");
+  assert.ok(block, "mermaid container rendered");
+
+  const { svg } = await mermaid.render("t1", block.textContent);
+  block.innerHTML = sanitizeSvg(svg);
+
+  const rendered = root.querySelector("svg");
+  assert.ok(rendered, "real <svg> inserted");
+  assert.equal(rendered.getAttribute("id"), "t1");
+  assert.ok(rendered.querySelectorAll("g.node").length >= 2, "diagram nodes present");
+  assert.match(block.innerHTML, /Start/);
+  assert.match(block.innerHTML, /End/);
+  assert.match(block.innerHTML, /class="flowchart/);
+  assert.doesNotMatch(block.innerHTML, /<script/i);
+});
