+import assert from "node:assert/strict";
+import { createHash, randomBytes } from "node:crypto";
+import { mkdtempSync, readFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { DatabaseSync } from "node:sqlite";
+import test from "node:test";
+import { startWebServer } from "../src/web.mjs";
+
+function seedSession(dbPath) {
+  const token = randomBytes(32).toString("base64url");
+  const db = new DatabaseSync(dbPath);
+  db.prepare("INSERT INTO sessions (token_hash, credential_id, created_at, expires_at) VALUES (?, ?, ?, ?)").run(
+    createHash("sha256").update(Buffer.from(token, "utf8")).digest(),
+    "test-cred",
+    Date.now(),
+    Date.now() + 3_600_000,
+  );
+  db.close();
+  return token;
+}
+
+test("markdown + mermaid routes, asset serving and unchanged auth gates", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "web-md-"));
+  const authDbPath = join(dir, "webauthn.sqlite");
+  let web = null;
+  try {
+    web = await startWebServer({
+      port: 0,
+      host: "127.0.0.1",
+      sockPath: join(dir, "swarm.sock"),
+      authDbPath,
+      rpId: "localhost",
+      origin: "http://localhost",
+    });
+    const base = `http://127.0.0.1:${web.server.address().port}`;
+
+    // mermaid.min.js is streamed from node_modules, byte for byte
+    const mermaid = await fetch(`${base}/assets/mermaid.min.js`);
+    assert.equal(mermaid.status, 200);
+    assert.match(mermaid.headers.get("content-type"), /javascript/);
+    const shipped = readFileSync(new URL("../node_modules/mermaid/dist/mermaid.min.js", import.meta.url));
+    assert.deepEqual(Buffer.from(await mermaid.arrayBuffer()), shipped);
+    assert.equal((await fetch(`${base}/assets/purify.min.js`)).status, 200);
+    assert.equal((await fetch(`${base}/assets/nope.js`)).status, 401);
+    assert.equal((await fetch(`${base}/healthz`)).status, 200);
+
+    // unauth gates preserved
+    assert.equal((await fetch(`${base}/api/markdown`, { method: "POST", body: "{}" })).status, 401);
+    assert.equal((await fetch(`${base}/api/chat`, { method: "POST", body: "{}" })).status, 401);
+    assert.match(await (await fetch(`${base}/`)).text(), /Unlock with passkey/);
+
+    const cookie = `__Host-s=${seedSession(authDbPath)}`;
+    const page = await (await fetch(`${base}/`, { headers: { cookie } })).text();
+    assert.match(page, /src="\/assets\/purify\.min\.js"/);
+    assert.match(page, /mermaid\.min\.js/);
+    const csp = (await fetch(`${base}/`, { headers: { cookie } })).headers.get("content-security-policy");
+    assert.match(csp, /script-src 'self' 'unsafe-inline'/);
+
+    const res = await fetch(`${base}/api/markdown`, {
+      method: "POST",
+      headers: { "Content-Type": "application/json", cookie },
+      body: JSON.stringify({
+        text: "# Hi\n\n<img src=x onerror=alert(1)>\n\n[j](javascript:alert(1))\n\n```js\nconst a = 1;\n```\n\n```mermaid\ngraph TD; A-->B\n```",
+      }),
+    });
+    assert.equal(res.status, 200);
+    const { html } = await res.json();
+    assert.match(html, /<h1>Hi<\/h1>/);
+    assert.match(html, /class="copy"/);
+    assert.match(html, /hljs-keyword/);
+    assert.match(html, /<pre class="mermaid">graph TD; A--&gt;B<\/pre>/);
+    assert.doesNotMatch(html, /onerror/i);
+    assert.doesNotMatch(html, /href="javascript:/i);
+  } finally {
+    web?.server.close();
+    web?.auth.close();
+    rmSync(dir, { recursive: true, force: true });
+  }
+});

