@@ -0,0 +1,55 @@
+#!/usr/bin/env -S node --no-warnings
+// Safe GFM Markdown -> sanitized HTML (DOMPurify/jsdom strict), hljs highlighting,
+// mermaid fences left as <pre class="mermaid"> for the client runtime.
+import DOMPurify from "dompurify";
+import hljs from "highlight.js/lib/common";
+import { JSDOM } from "jsdom";
+import { Marked } from "marked";
+
+const purify = DOMPurify(new JSDOM("").window);
+
+const ESC = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
+const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ESC[c]);
+
+// Strict: no raw javascript:, no data:text/html, no event handlers, no <script>/<style>
+const PURIFY_OPTS = {
+  USE_PROFILES: { html: true },
+  ADD_ATTR: ["target", "rel"],
+  FORBID_TAGS: ["script", "style", "iframe", "object", "embed", "form", "input", "textarea", "select"],
+  FORBID_ATTR: ["style", "onerror", "srcset"],
+  // allowlisted schemes + relative URLs; javascript: and data:text/html dropped
+  ALLOWED_URI_REGEXP:
+    /^(?:(?:https?|mailto|tel):|data:image\/(?:png|jpe?g|gif|webp|bmp|avif|svg\+xml)[;,)])|^[^a-z]|^[a-z+.\-]+(?:[^a-z+.\-:]|$)/i,
+};
+
+const marked = new Marked({ gfm: true, breaks: true });
+marked.use({
+  renderer: {
+    code(token) {
+      const lang = String(token.lang || "").trim().split(/\s+/)[0].toLowerCase();
+      if (lang === "mermaid") return `<pre class="mermaid">${esc(token.text)}</pre>\n`;
+      const cls = lang && hljs.getLanguage(lang) ? ` class="hljs language-${esc(lang)}"` : ' class="hljs"';
+      const body = lang && hljs.getLanguage(lang)
+        ? hljs.highlight(token.text, { language: lang, ignoreIllegals: true }).value
+        : esc(token.text);
+      return `<div class="cb"><button type="button" class="copy" aria-label="Copy code">Copy</button><pre><code${cls}>${body}</code></pre></div>\n`;
+    },
+    link(token) {
+      const title = token.title ? ` title="${esc(token.title)}"` : "";
+      return `<a href="${esc(token.href)}"${title} target="_blank" rel="noopener noreferrer">${this.parser.parseInline(token.tokens)}</a>`;
+    },
+    image(token) {
+      const title = token.title ? ` title="${esc(token.title)}"` : "";
+      return `<img src="${esc(token.href)}" alt="${esc(token.text)}"${title} loading="lazy">`;
+    },
+  },
+});
+
+export function renderMarkdown(md) {
+  const source = String(md ?? "");
+  if (!source) return "";
+  const raw = marked.parse(source);
+  return purify.sanitize(raw, PURIFY_OPTS);
+}
+
+export default renderMarkdown;
