+++ b/src/markdown.mjs
@@ -0,0 +1,52 @@
+// GFM Markdown -> sanitized HTML for the web chat UI.
+// Pipeline: marked (GFM) -> highlight.js (server-side, fenced code) -> DOMPurify (jsdom, strict XSS scrub).
+import hljs from "highlight.js/lib/common.js";
+import { JSDOM } from "jsdom";
+import { marked } from "marked";
+import DOMPurify from "dompurify";
+
+const purifyWindow = new JSDOM("<!doctype html><html><body></body></html>").window;
+const DOMPurifySrv = DOMPurify(purifyWindow);
+
+function escapeHtml(s) {
+  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
+}
+
+marked.use({
+  gfm: true,
+  breaks: true,
+  renderer: {
+    code({ text, lang }) {
+      const language = String(lang || "").trim().split(/\s+/)[0].toLowerCase();
+      if (language === "mermaid") {
+        // Raw diagram text preserved for the browser (mermaid.min.js renders it with securityLevel:'strict').
+        return `<pre class="mermaid"><code class="language-mermaid">${escapeHtml(text)}</code></pre>\n`;
+      }
+      let body;
+      if (language && hljs.getLanguage(language)) {
+        body = hljs.highlight(text, { language, ignoreIllegals: true }).value;
+      } else {
+        body = escapeHtml(text);
+      }
+      const cls = language && hljs.getLanguage(language) ? `hljs language-${language}` : `language-${language || "plaintext"}`;
+      return `<pre class="code-block" data-lang="${language || "text"}"><code class="${cls}">${body}</code></pre>\n`;
+    },
+  },
+});
+
+// Strict sanitize: keep normal Markdown/HTML output + hljs spans + our mermaid/code-block pre markers,
+// drop scripts, event handlers (onerror etc.), javascript:/data:text-html URLs, iframes, svg script tricks.
+const PURIFY_CONFIG = {
+  USE_PROFILES: { html: true },
+  ALLOWED_ATTR: [
+    "href", "src", "alt", "title", "class", "id", "colspan", "rowspan", "align", "start", "type",
+    "data-lang", "rel",
+  ],
+  FORBID_TAGS: ["style", "form", "input", "button", "iframe", "object", "embed", "base", "meta", "link"],
+  FORBID_ATTR: ["style", "srcset", "sizes"],
+};
+
+export function renderMarkdown(markdown) {
+  const raw = marked.parse(String(markdown ?? ""), { async: false });
+  return DOMPurifySrv.sanitize(raw, PURIFY_CONFIG);
+}
