@@ -0,0 +1,62 @@
+/* Client-side chat enhancement. Server HTML is already DOMPurify-sanitized.
+   - Adds Copy buttons to highlighted code blocks (pre.code-block).
+   - Converts pre.mermaid blocks to real SVG via mermaid.min.js (securityLevel:'strict'). */
+(function () {
+  "use strict";
+  function enhanceCopy(root) {
+    var pres = root.querySelectorAll("pre.code-block");
+    for (var i = 0; i < pres.length; i++) {
+      var pre = pres[i];
+      if (pre.querySelector(".copy-btn")) continue;
+      var code = pre.querySelector("code");
+      if (!code) continue;
+      var btn = document.createElement("button");
+      btn.type = "button";
+      btn.className = "copy-btn";
+      btn.setAttribute("aria-label", "Copy code");
+      btn.textContent = "Copy";
+      btn.addEventListener("click", function () {
+        var self = this;
+        var pre = self.parentNode;
+        var codeEl = pre.querySelector("code");
+        var txt = codeEl ? codeEl.textContent : "";
+        var done = function () {
+          self.textContent = "Copied!";
+          setTimeout(function () { self.textContent = "Copy"; }, 1200);
+        };
+        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).then(done, done);
+        else done();
+      });
+      pre.appendChild(btn);
+    }
+  }
+  function renderMermaidDiagrams() {
+    if (!window.mermaid) return Promise.resolve();
+    var pres = document.querySelectorAll("pre.mermaid");
+    var divs = [];
+    for (var i = 0; i < pres.length; i++) {
+      var pre = pres[i];
+      if (pre.getAttribute("data-md-done")) continue;
+      pre.setAttribute("data-md-done", "1");
+      var code = pre.querySelector("code");
+      var text = code ? code.textContent : pre.textContent;
+      var div = document.createElement("div");
+      div.className = "mermaid";
+      div.setAttribute("data-src", text);
+      div.textContent = text;
+      divs.push(div);
+      pre.parentNode.replaceChild(div, pre);
+    }
+    if (!divs.length) return Promise.resolve();
+    window.mermaid.initialize({ startOnLoad: false, securityLevel: "strict" });
+    return window.mermaid.run({ nodes: divs }).catch(function () {
+      for (var j = 0; j < divs.length; j++) {
+        if (!divs[j].querySelector("svg")) divs[j].textContent = divs[j].getAttribute("data-src") || "";
+      }
+    });
+  }
+  window.mdEnhance = function () {
+    enhanceCopy(document);
+    return renderMermaidDiagrams();
+  };
+})();
